#!/usr/bin/env python3
# =====================================================================
#  apply_test_fixes.py  —  fence TEST_FIXES_20261126   (on main aa1c3685, v12.0.19)
#  DEF-088 · DEF-089 · DEF-092 · TD-099 · TD-100
#
#  DEF-088 / DEF-089: the portfolio PDF and EOD card suites failed only
#  because backend/venv's matplotlib lost 15 of its 40 font files on 30 Oct
#  (DejaVuSans.ttf, all of DejaVu Sans Mono …): text fell back to a wider
#  font. The installed app (76 font files) and the build venv are complete.
#  Now those suites check the fonts first and fail with ONE line naming the
#  missing files and the repair command, and scalp-backend.spec stops a build
#  whose matplotlib lacks them. A repaired install can still fail the same
#  way while matplotlib's font cache (~/.matplotlib/fontlist-v*.json) predates
#  the fonts: the suites catch that too. This script refuses to run until both
#  are right (it prints the command).
#  DEF-092: TC-CALM-0021 clicked the first unpressed button in the hero —
#  since the This week / This month chips that is "Week", not "Paper". It now
#  clicks the Live | Paper switch. The app is unchanged. The suite also finds
#  Chrome on a Mac by itself.
#
#   backend/app/utils/mpl_fonts.py                       NEW — missing_fonts / require_fonts
#   backend/app/utils/test_mpl_fonts.py                  NEW — TC-UTIL-0030…0036
#   backend/app/tests/test_eod_card_v2.py                fonts checked first
#   backend/app/backtest/report/test_portfolio_pdf_codename.py   same
#   backend/app/backtest/report/test_portfolio_pdf_redact.py     same
#   backend/scalp-backend.spec                           build stops without the fonts
#   frontend/uitest/test_ui_calm.py                      TC-CALM-0021 clicks the Live | Paper switch
#  Build copies under desktop/src-tauri/ are written too when present.
#  Every edited file gets a .bak-TEST_FIXES_20261126 copy.
#
#  First (once):  backend/venv/bin/python -m pip install --force-reinstall --no-deps matplotlib==3.10.9
#  Run ONLY this script:
#     cd ~/dev/scalp-app && python3 apply_test_fixes.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "TEST_FIXES_20261126"
ITEMS = json.loads(r'''[{"path": "backend/app/utils/mpl_fonts.py", "orig": null, "new": "aef412f34cb377788879481cf6e5abdab81854f34541f579445abc1e19b2bc4b", "blob": ""}, {"path": "backend/app/utils/test_mpl_fonts.py", "orig": null, "new": "d9d175a6523746797582e79d7775edc3e4ec1242941ab907bd50af61d2f736d7", "blob": ""}, {"path": "backend/app/tests/test_eod_card_v2.py", "orig": "2336d9b55040bdea3f7a8489f7891b967940aa0dd4acc1a7966405dfe8e7c296", "new": "fffcf802a05292589c307045c6e7dee514600f49eb5741893db2b316ecb132e7", "blob": ""}, {"path": "backend/app/backtest/report/test_portfolio_pdf_codename.py", "orig": "50cf0dbd19b8869fa68256779a00be06049dd517f0e4c9281283a640ae4e8270", "new": "1d5174f97510eb467520062879f709c62068580e13085e1729f0bf9a9934e2f8", "blob": ""}, {"path": "backend/app/backtest/report/test_portfolio_pdf_redact.py", "orig": "fc9e13f55c64d63e2a0968dec47289b759908e03420a669dcd1781ad529de19b", "new": "cc501b821bc4a4a3826fbb6cd90e3cae59c1ef9415e2e91fc32b1726e9aa8601", "blob": ""}, {"path": "backend/scalp-backend.spec", "orig": "dae7ecc103030089d50c45a500b9b2598f84fa8867fe505f37e61f067fc6598f", "new": "cd95eab8f9cdba639626b94671fc23985ae0e617ecb63f6d581f0c9bd413301d", "blob": ""}, {"path": "frontend/uitest/test_ui_calm.py", "orig": "b2a47236be2d590759b319db5d6134a67ac73331bce34901c1e90c50030bd0cb", "new": "e89ac72b181b44a1e73f61630ef0108389eb5a91f59066e76fc7a8ab4b1d1832", "blob": ""}]''')

BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [["backend", "app/utils/test_mpl_fonts.py"], ["backend", "app/tests/test_eod_card_v2.py"], ["backend", "app/backtest/report/test_portfolio_pdf_codename.py"], ["backend", "app/backtest/report/test_portfolio_pdf_redact.py"]]   # [where, path]: 'backend' = run from backend/, 'root' = from the repo root


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── parent fences: the code this patches ─────────────────────────────
PARENTS = {"backend/app/tests/test_eod_card_v2.py": ["EOD_CARD_FIX_20261001"], "backend/app/backtest/report/test_portfolio_pdf_codename.py": ["PF_PDF_CODENAME_20261015"], "backend/app/backtest/report/test_portfolio_pdf_redact.py": ["PF_PDF_REDACT_20261015"], "backend/scalp-backend.spec": ["APP_SUBMODULES END", "WINDOWS_SSL_STRIP_FIX"], "frontend/uitest/test_ui_calm.py": ["CLOSED_METER_20261120"]}
if "--rollback" not in args:
    for _rel, _fs in PARENTS.items():
        _pf = os.path.join(repo, _rel)
        _txt = open(_pf, encoding="utf-8").read() if os.path.exists(_pf) else ""
        _miss = [f for f in _fs if f not in _txt]
        if _miss:
            die(f"{_rel} lacks {', '.join(_miss)} — pull the latest main first")


def refresh_master():
    """MASTER_SUITE.md and REPO_MAP.md follow the suites on disk (a new uitest file)."""
    for gen, a_, name in (("scripts/regression/master_suite.py", ["refresh"], "MASTER_SUITE.md"),
                          ("scripts/gen_repo_map.py", [], "REPO_MAP.md")):
        g = os.path.join(repo, gen)
        if not os.path.exists(g):
            continue
        r = subprocess.run([sys.executable, g] + a_, cwd=repo, capture_output=True, text=True, timeout=300)
        msg = ((r.stdout or "") + (r.stderr or "")).strip().splitlines()
        say("  " + (msg[-1] if msg else f"{name} refreshed") if r.returncode == 0
            else f"  !! {name} refresh failed — pre-commit will refresh it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    refresh_master()
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 0. pre-flight: the guarded suites need matplotlib's DejaVu fonts, and a font cache that knows them ──
_PRE_CODE = r"""
import matplotlib, os, glob, matplotlib.font_manager as fm
d = os.path.join(matplotlib.get_data_path(), 'fonts', 'ttf')
print(matplotlib.__version__)
print(' '.join(f for f in ('DejaVuSans.ttf', 'DejaVuSans-Bold.ttf', 'DejaVuSansMono.ttf', 'DejaVuSansMono-Bold.ttf')
               if not os.path.isfile(os.path.join(d, f))))
def _f(fam):
    try:
        return os.path.basename(fm.findfont(fm.FontProperties(family=fam), fallback_to_default=False))
    except Exception:
        return ''
print(' '.join(fam.replace(' ', '_') for fam, fn in (('DejaVu Sans', 'DejaVuSans.ttf'), ('DejaVu Sans Mono', 'DejaVuSansMono.ttf'))
               if _f(fam) != fn))
print(' '.join(sorted(glob.glob(os.path.join(matplotlib.get_cachedir(), 'fontlist-v*.json')))))
"""
if "--skip-tests" not in args:
    _b = os.path.join(repo, "backend")
    _py = next((c for c in (os.path.join(_b, "venv", "bin", "python"), os.path.join(_b, ".venv", "bin", "python"))
                if os.path.exists(c)), sys.executable)
    _r = subprocess.run([_py, "-c", _PRE_CODE], capture_output=True, text=True, timeout=180)
    _lines = (_r.stdout or "").splitlines() + ["", "", "", ""]
    if _r.returncode == 0 and _lines[1].strip():
        die(f"{_py}'s matplotlib {_lines[0]} is missing {_lines[1]} (DEF-088/089) — the card / PDF suites this "
            f"script runs would fail for that reason. Repair it first, then run this script again:\n"
            f"     {_py} -m pip install --force-reinstall --no-deps matplotlib=={_lines[0]}")
    if _r.returncode == 0 and _lines[2].strip():
        die(f"{_py}'s matplotlib font cache is stale: {_lines[2].replace('_', ' ')} not found although the files are "
            f"there (DEF-088/089). Delete the cache (matplotlib rebuilds it), then run this script again:\n"
            f"     rm {_lines[3] or '<cachedir>/fontlist-v*.json'}")

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # a planned file was just proven byte-identical to its expected base (sha == orig): only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="test_fixes_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, it["path"].replace("/", "_"))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        _mode = os.stat(p).st_mode if cur is not None else None
        if cur is not None:
            shutil.copy2(p, p + ".bak-" + FENCE)            # keeps the mode for --rollback
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        if _mode is not None:
            os.chmod(t, _mode)
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")
refresh_master()

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for where, t in TESTS:
        cwd = backend if where == "backend" else repo
        if not os.path.exists(os.path.join(cwd, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=cwd, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        # the project venv can lag requirements.txt (PyJWT): retry such a suite with this Python
        if (r is not None and r.returncode != 0 and "ModuleNotFoundError" in outp
                and "No module named 'app" not in outp and os.path.realpath(sys.executable) != os.path.realpath(py)):
            try:
                r = subprocess.run([sys.executable, t], cwd=cwd, env=env, capture_output=True, text=True, timeout=900)
                outp = (r.stdout or "") + (r.stderr or "")
            except subprocess.TimeoutExpired:
                r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        refresh_master()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        refresh_master()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)).")
say("  UI check, APP CLOSED: cd frontend && CI=false npm run build && PYTHONPATH=../backend python3 uitest/test_ui_calm.py")
say("  Commit with the other change; nothing here ships in the app except the build-time font check.")
say("  Undo: python3 apply_test_fixes.py --rollback")
